def task_func(script_path: str, timeout: int = 60) -> str:
    """
    Execute a specified python code with a given timeout. If the script execution exceeds the timeout, it is terminated.

    Parameters:
    - script_path (str):
    try:
            with open(script_path, 'r') as file:
                script = file.read()
        except FileNotFoundError:
            raise FileNotFoundError(f"File not found: {script_path}")

        def run_script():
            try:
                subprocess.run(['python', script_path], timeout=timeout)
            except subprocess.TimeoutExpired:
                print("Terminating process due to timeout.")
                os.killpg(os.getpgid(subprocess.Popen(['python', script_path]).pid), 9)

        thread = threading.Thread(target=run_script)
        thread.start()
        thread.join(timeout)
        if thread.is_alive():
            thread.terminate()
            thread.join()
            return "Terminating process due to timeout."
        else:
            return "Script executed successfully."

