            raise ValueError("Path must be a string.")

        if not path:
            raise ValueError("Path cannot be empty.")

        if not os.path.exists(path):
            raise FileNotFoundError(f"Path '{path}' does not exist.")

        components = path.split(delimiter)
        if len(components) == 1:
            return [(path, {'total': os.path.getsize(path), 'used': 0, 'free': 0})]

        disk_usage = {}
        for i, component in enumerate(components):
            if not component:
                raise ValueError(f"Invalid component '{component}' at index {i}.")

            if i == 0:
                disk_usage['total'] = os.path.getsize(path)
            else:
                if not os.path.exists(component):
                    raise FileNotFoundError(f"Path '{component}' does not exist.")
                disk_usage['total'] += os.path.getsize(component)

        return [(component, disk_usage) for component in components]
